{path=src/main/java/com/wolinski/shop/orders/internal/OrderService.java, content=package com.wolinski.shop.orders.internal;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import com.wolinski.shop.orders.api.OrderSummary;
import java.time.Clock;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.UUID;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderService implements OrderFacade {

    private static final ZoneId BUSINESS_ZONE = ZoneId.of("Europe/Warsaw");
    private static final int STALE_AFTER_DAYS = 30;

    private final OrderRepository orders;
    private final Clock clock;

    public OrderService(OrderRepository orders, Clock clock) {
        this.orders = orders;
        this.clock = clock;
    }

    @Override
    @Transactional
    public String place(String customerId, Money total, java.time.Instant placedAt) {
        Order order = new Order(UUID.randomUUID().toString(), customerId, total, placedAt);
        orders.save(order);
        return order.id();
    }

    @Override
    @Transactional
    public void confirm(String orderId) {
        orders.get(orderId).changeStatus("CONFIRMED");
    }

    @Override
    @Transactional
    public void cancel(String orderId) {
        orders.get(orderId).changeStatus("CANCELLED");
    }

    @Override
    @Transactional(readOnly = true)
    public OrderSummary summary(String orderId) {
        Order order = orders.get(orderId);
        return new OrderSummary(order.id(), order.customerId(), order.total(), order.status());
    }

    @Override
    @Transactional
    public int expireStale() {
        // Calendar days are counted in the business zone (ADR 12).
        LocalDate cutoff = LocalDate.now(clock.withZone(BUSINESS_ZONE)).minusDays(STALE_AFTER_DAYS);
        int cancelled = 0;
        for (Order order : orders.all()) {
            boolean stale = order.placedAt().atZone(BUSINESS_ZONE).toLocalDate().isBefore(cutoff);
            if (stale && "PLACED".equals(order.status())) {
                order.changeStatus("CANCELLED");
                cancelled++;
            }
        }
        return cancelled;
    }
}
}

