import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceTest {

    // 2026-10-31 02:00 Warsaw (CET, UTC+1) is 01:00 UTC.
    private static final Clock NIGHT = Clock.fixed(Instant.parse("2026-10-31T01:00:00Z"), ZoneOffset.UTC);

    @Test
    void cancelsOnlyPlacedOrdersOlderThanThirtyDays() {
        OrderRepository repo = new OrderRepository();
        OrderService service = new OrderService(repo, NIGHT);

        // 31 days ago, still PLACED: cancelled.
        Order old = new Order("old", "c", Money.pln(100), Instant.parse("2026-09-30T10:00:00Z"));
        // 31 days ago, but already CONFIRMED: left alone.
        Order oldConfirmed = new Order("oldConfirmed", "c", Money.pln(100), Instant.parse("2026-09-30T10:00:00Z"));
        oldConfirmed.changeStatus("CONFIRMED");
        // Exactly 30 days ago: not more than 30 days, left alone.
        Order edge = new Order("edge", "c", Money.pln(100), Instant.parse("2026-10-01T10:00:00Z"));
        // Recent: left alone.
        Order recent = new Order("recent", "c", Money.pln(100), Instant.parse("2026-10-30T10:00:00Z"));
        repo.save(old);
        repo.save(oldConfirmed);
        repo.save(edge);
        repo.save(recent);

        assertEquals(1, service.expireStale());

        assertEquals("CANCELLED", old.status());
        assertEquals("CONFIRMED", oldConfirmed.status());
        assertEquals("PLACED", edge.status());
        assertEquals("PLACED", recent.status());
    }

    @Test
    void usesTheWarsawCalendarDay() {
        OrderRepository repo = new OrderRepository();
        OrderService service = new OrderService(repo, NIGHT);

        // 2026-10-01 00:30 Warsaw is 2026-09-30 22:30 UTC. Its Warsaw date is 10-01, so it is
        // exactly 30 days old and must not be cancelled, even though the UTC date is 09-30.
        Order order = new Order("o", "c", Money.pln(100), Instant.parse("2026-09-30T22:30:00Z"));
        repo.save(order);

        assertEquals(0, service.expireStale());
        assertEquals("PLACED", order.status());
    }

    @Test
    void returnsZeroWhenNothingIsStale() {
        assertEquals(0, new OrderService(new OrderRepository(), NIGHT).expireStale());
    }
}
}
